 for label,num in zip(['Systolic','Diastolic'],map(float,pair.split('/'))):obs(g,label+' admission blood pressure',n,q,kind='vital',numeric_value=num,comparator='=',text_value=pair,flag='unknown',_notes='Component representation of same pair; pair-level elevated label does not classify both components; unit not explicitly printed.')
