 q=B[f'b{n:05d}'].split('\n')[-1];cells=q.split(' | ');age=float(cells[1]);add('history','demographics','Age when stroke occurred',n,q,attribute='age_other',numeric_value=age,unit='years',time=tm('Age when stroke occurred','at'),_extra=[ev(n,'Age when stroke occurred')],_notes='Table explicitly scopes age to stroke; body description age retained separately, without invented interval.' if i==1 else 'Same reported stroke age as case text, alternate role-specific representation.')
